// Validate Request: checks the JSON payload sent by Bubble (author + books). Webhook authentication
// (shared-secret header) is enforced by n8n's Header Auth credential before this node runs.
const j = $input.first().json;
const b = (j && j.body && typeof j.body === 'object') ? j.body : {};
const errors = [];

const a = (b.author && typeof b.author === 'object') ? b.author : {};
const author = {
  author_id: typeof a.author_id === 'string' ? a.author_id.trim() : '',
  name: typeof a.name === 'string' ? a.name.trim() : '',
  email: typeof a.email === 'string' ? a.email.trim() : '',
  city: typeof a.city === 'string' ? a.city.trim() : '',
};
if (!author.author_id) errors.push('author.author_id is missing');
else if (!/^AUTH\d{3,}$/.test(author.author_id)) errors.push('author.author_id has an invalid format (expected e.g. AUTH001)');
if (!author.name) errors.push('author.name is missing');

if (!Array.isArray(b.books)) errors.push('books must be a list');
const books = Array.isArray(b.books) ? b.books.filter((x) => x && typeof x === 'object') : [];

const trigger = ['Single', 'Bulk'].includes(b.trigger) ? b.trigger : 'Single';

return [{
  json: {
    valid: errors.length === 0,
    errors,
    author_id: author.author_id,
    author,
    books,
    request_id: (typeof b.request_id === 'string' && b.request_id.trim()) || `${author.author_id}-${Date.now()}`,
    trigger,
    execution_id: $execution.id,
    received_at: new Date().toISOString(),
  },
}];

// Duplicate Guard (idempotency): the same author (or the same request_id) inside the window is ignored.
// State lives in n8n workflow static data, which persists between production executions.
const v = $input.first().json;
const WINDOW_MS = 60 * 1000;
const sd = $getWorkflowStaticData('global');
sd.recent = sd.recent || {};
const now = Date.now();

for (const k of Object.keys(sd.recent)) {
  if (now - sd.recent[k].t > WINDOW_MS * 10) delete sd.recent[k];
}

const prev = sd.recent[v.author_id];
const sameRequest = Object.values(sd.recent).some((e) => e.request_id === v.request_id);
let duplicate = false;
let reason = '';
if (prev && now - prev.t < WINDOW_MS) {
  duplicate = true;
  reason = `Duplicate request ignored: ${v.author_id} was already triggered ${Math.round((now - prev.t) / 1000)}s ago`;
} else if (sameRequest) {
  duplicate = true;
  reason = `Duplicate request ignored: request_id ${v.request_id} was already processed`;
}

if (!duplicate) sd.recent[v.author_id] = { t: now, request_id: v.request_id };

return [{ json: { ...v, duplicate, duplicate_reason: reason } }];

// Calculate: deterministic royalty summary. NO AI involved. Supplied Bubble figures are never overwritten;
// they are validated, summed in integer paise (no float drift) and checked for consistency.
const req = $('Duplicate Guard').first().json;
const author = req.author;
const cfg = $('Settings').first().json;
const raw = Array.isArray(req.books) ? req.books : [];

if (raw.length === 0) {
  throw new Error(`No books were sent for ${author.author_id} (${author.name}); nothing to summarise`);
}

const OVERDUE_DAYS = Number(cfg.overdue_days) || 90;
const WINDOW_DAYS = Number(cfg.payout_window_days) || 45;
const now = cfg.today_override ? new Date(cfg.today_override) : new Date();
if (isNaN(now.getTime())) throw new Error('Invalid today_override setting');
const DAY = 86400000;

const norm = (o) => {
  const r = {};
  for (const k of Object.keys(o)) r[k.toLowerCase().replace(/[^a-z0-9]/g, '')] = o[k];
  return r;
};
const pick = (o, ...names) => {
  for (const n of names) if (o[n] !== undefined && o[n] !== null && o[n] !== '') return o[n];
  return null;
};
// Returns null when missing; throws on non-numeric / negative / non-finite values.
const num = (v, field, label) => {
  if (v === null || v === undefined || v === '') return null;
  const x = typeof v === 'number' ? v : (typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN);
  if (!Number.isFinite(x)) throw new Error(`Invalid ${field} "${v}" for ${label}`);
  if (x < 0) throw new Error(`Negative ${field} (${x}) for ${label}`);
  return x;
};
const cents = (x) => Math.round(x * 100);
const rupees = (c) => c / 100;
const asDate = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d;
};
const iso = (d) => (d ? d.toISOString().slice(0, 10) : null);

const warnings = [];
const books = [];
let tEarned = 0, tPaid = 0, tPending = 0;

for (const rb of raw) {
  const b = norm(rb);
  const bookId = pick(b, 'bookid') || rb._id;
  const title = pick(b, 'title', 'booktitle', 'name') || '(untitled)';
  const label = `book ${bookId} "${title}"`;
  const status = String(pick(b, 'status') || '').trim();
  const published = /^published/i.test(status);
  const inProduction = /^in production/i.test(status);

  const copies = num(pick(b, 'copiessold', 'totalcopiessold'), 'copies sold', label);
  const rate = num(pick(b, 'authorroyaltypercopy', 'royaltypercopy'), 'royalty per copy', label);
  const mrp = num(pick(b, 'mrp'), 'MRP', label);
  const earned = num(pick(b, 'royaltyearned', 'totalroyaltyearned'), 'royalty earned', label);
  const paid = num(pick(b, 'royaltypaid'), 'royalty paid', label);
  const pending = num(pick(b, 'royaltypending'), 'royalty pending', label);

  if (published && (earned === null || paid === null || pending === null)) {
    throw new Error(`Missing royalty fields (earned/paid/pending) for published ${label}`);
  }
  const eC = cents(earned ?? 0), paC = cents(paid ?? 0), peC = cents(pending ?? 0);

  if (published && earned !== null && paid !== null && pending !== null && eC - paC !== peC) {
    warnings.push(`${label}: pending (${pending}) differs from earned - paid (${rupees(eC - paC)})`);
  }
  if (published && copies !== null && rate !== null && earned !== null && cents(copies * rate) !== eC) {
    warnings.push(`${label}: earned (${earned}) differs from copies x rate (${rupees(cents(copies * rate))})`);
  }

  const pubDate = asDate(pick(b, 'publication', 'publicationdate'));
  const lastPayout = asDate(pick(b, 'lastpayout', 'lastroyaltypayoutdate'));

  // Royalty status badge (brief, A2): Green = nothing pending; Red = pending AND (last payout > 90 days ago,
  // or never paid for a published book older than 90 days); Yellow = pending but within the normal cycle.
  let badge = 'n/a';
  if (published) {
    if (peC === 0) badge = 'green';
    else if (lastPayout) badge = (now - lastPayout) / DAY > OVERDUE_DAYS ? 'red' : 'yellow';
    else badge = pubDate && (now - pubDate) / DAY > OVERDUE_DAYS ? 'red' : 'yellow';
  }

  if (published) { tEarned += eC; tPaid += paC; tPending += peC; }

  books.push({
    book_id: bookId,
    title,
    status,
    published,
    in_production: inProduction,
    genre: pick(b, 'genre'),
    isbn: pick(b, 'isbn'),
    publication_date: iso(pubDate),
    mrp,
    royalty_per_copy: rate,
    copies_sold: copies ?? 0,
    royalty_earned: rupees(eC),
    royalty_paid: rupees(paC),
    royalty_pending: rupees(peC),
    last_payout_date: iso(lastPayout),
    badge,
    platforms: Array.isArray(pick(b, 'platforms')) ? pick(b, 'platforms') : [],
  });
}

if (!books.some((b) => b.published) && !books.some((b) => b.in_production)) {
  throw new Error(`No usable books for ${author.author_id}`);
}
if (tEarned - tPaid !== tPending) {
  warnings.push(`Totals: pending (${rupees(tPending)}) differs from earned - paid (${rupees(tEarned - tPaid)})`);
}

// Payout timing (brief B): payouts are quarterly with a 45-day window. Royalties for a finished quarter are
// expected within 45 days after quarter end; if that window has already passed, the next window applies.
const quarterEnd = (d, offset) => {
  const q = Math.floor(d.getUTCMonth() / 3) + offset;
  const year = d.getUTCFullYear() + Math.floor(q / 4);
  const qi = ((q % 4) + 4) % 4;
  return new Date(Date.UTC(year, qi * 3 + 3, 0));
};
const prevEnd = quarterEnd(now, -1);
const currEnd = quarterEnd(now, 0);
const prevWindowEnd = new Date(prevEnd.getTime() + WINDOW_DAYS * DAY);
const currWindowEnd = new Date(currEnd.getTime() + WINDOW_DAYS * DAY);
const useWindow = prevWindowEnd >= now ? prevWindowEnd : currWindowEnd;
const useQuarterEnd = prevWindowEnd >= now ? prevEnd : currEnd;

const hasPending = tPending > 0;
return [{
  json: {
    author,
    reference_date: iso(now),
    books,
    totals: { earned: rupees(tEarned), paid: rupees(tPaid), pending: rupees(tPending) },
    flags: {
      has_pending: hasPending,
      all_paid: !hasPending && books.some((b) => b.published),
      has_overdue: books.some((b) => b.badge === 'red'),
      in_production_count: books.filter((b) => b.in_production).length,
    },
    next_payout: hasPending ? {
      quarter_end: iso(useQuarterEnd),
      expected_by: iso(useWindow),
    } : null,
    warnings,
  },
}];

// Build Prompt: the AI only receives pre-calculated, verified facts and writes the wording.
const facts = $input.first().json;
const cfg = $('Settings').first().json;

const inr = (x) => '₹' + Number(x).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const authorFacts = {
  author_name: facts.author.name,
  reference_date: facts.reference_date,
  published_books: facts.books.filter((b) => b.published).map((b) => ({
    title: b.title,
    copies_sold: b.copies_sold,
    royalty_earned: inr(b.royalty_earned),
    royalty_paid: inr(b.royalty_paid),
    royalty_pending: inr(b.royalty_pending),
    last_payout_date: b.last_payout_date || 'no payout has been made yet',
  })),
  books_in_production: facts.books.filter((b) => b.in_production).map((b) => ({
    title: b.title,
    stage: b.status,
  })),
  totals: {
    total_earned: inr(facts.totals.earned),
    total_paid: inr(facts.totals.paid),
    total_pending: inr(facts.totals.pending),
  },
  all_royalties_paid: facts.flags.all_paid,
  next_payout: facts.next_payout
    ? { expected_by: facts.next_payout.expected_by, quarter_end: facts.next_payout.quarter_end }
    : null,
};

const system = [
  'You write royalty summary emails for BookLeaf Publishing authors.',
  'Tone: warm, professional, clear and respectful. Plain language, no hype, no jargon.',
  'STRICT RULES:',
  '1. Use ONLY the facts in the JSON provided. Never invent, estimate, round or recalculate any number, date, title or status.',
  '2. Copy every rupee amount exactly as written in the JSON (including the ₹ symbol).',
  '3. Greet the author by name. Summarise each published book (copies sold, earned, paid, pending, last payout date).',
  '4. Give a clear breakdown of total earned, total paid and total pending.',
  '5. If next_payout is not null, explain that BookLeaf pays royalties quarterly and that payment is expected within 45 days of the quarter end, naming the expected_by date. Do not promise an exact payment day.',
  '6. If all_royalties_paid is true, warmly acknowledge that everything is paid up.',
  '7. If books_in_production is not empty, add a short status update for each such book (title and stage only).',
  '8. End with a warm, professional closing signed "Team BookLeaf".',
  'Return JSON with exactly two string fields: "subject" and "body" (plain text, paragraphs separated by blank lines).',
].join('\n');

const geminiBody = {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: 'Facts (JSON):\n' + JSON.stringify(authorFacts, null, 2) }] }],
  generationConfig: {
    temperature: 0.3,
    maxOutputTokens: 2000,
    thinkingConfig: { thinkingLevel: 'low' },
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: { subject: { type: 'STRING' }, body: { type: 'STRING' } },
      required: ['subject', 'body'],
    },
  },
};

return [{ json: { geminiBody, model: cfg.gemini_model } }];

// Compose Email: validates the AI output against the calculated facts; on any problem (AI error, bad JSON,
// invented amounts, missing author name/pending total) it falls back to a deterministic template.
const facts = $('Calculate').first().json;
const input = $input.first().json || {};

const inr = (x) => '₹' + Number(x).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const published = facts.books.filter((b) => b.published);
const production = facts.books.filter((b) => b.in_production);

function template() {
  const lines = [`Dear ${facts.author.name},`, '', 'Here is your royalty summary from BookLeaf Publishing.', ''];
  for (const b of published) {
    lines.push(`• ${b.title}: ${b.copies_sold} copies sold; royalty earned ${inr(b.royalty_earned)}, paid ${inr(b.royalty_paid)}, pending ${inr(b.royalty_pending)}; ` +
      `last payout: ${b.last_payout_date || 'no payout made yet'}.`);
  }
  lines.push('', `Total earned: ${inr(facts.totals.earned)}`, `Total paid: ${inr(facts.totals.paid)}`, `Total pending: ${inr(facts.totals.pending)}`, '');
  if (facts.flags.has_pending && facts.next_payout) {
    lines.push(`BookLeaf pays royalties quarterly, and payment is expected within 45 days of the quarter end. Your next payout is expected by ${facts.next_payout.expected_by}.`, '');
  } else if (facts.flags.all_paid) {
    lines.push('Great news: all of your royalties are fully paid up. Thank you for being part of BookLeaf!', '');
  }
  for (const b of production) {
    lines.push(`Update: "${b.title}" is currently in production (${b.status}).`);
  }
  if (production.length) lines.push('');
  lines.push('If you have any questions, simply reply to this email and we will be happy to help.', '', 'Warm regards,', 'Team BookLeaf');
  return { subject: 'Your BookLeaf royalty summary', body: lines.join('\n') };
}

// ---- allowed numbers (everything the AI is permitted to quote in rupees)
const allowed = new Set();
const add = (x) => { if (typeof x === 'number' && Number.isFinite(x)) allowed.add(x.toFixed(2)); };
['earned', 'paid', 'pending'].forEach((k) => add(facts.totals[k]));
for (const b of facts.books) {
  ['royalty_earned', 'royalty_paid', 'royalty_pending', 'mrp', 'royalty_per_copy'].forEach((k) => add(b[k]));
}

function checkAi(text) {
  let parsed;
  try { parsed = JSON.parse(text); } catch (e) { return { ok: false, why: 'AI response was not valid JSON' }; }
  if (!parsed || typeof parsed.subject !== 'string' || typeof parsed.body !== 'string' ||
      !parsed.subject.trim() || parsed.body.trim().length < 80) {
    return { ok: false, why: 'AI response missing subject/body or too short' };
  }
  const re = /(?:₹|Rs\.?\s?|INR\s?)\s*([\d,]+(?:\.\d{1,2})?)/gi;
  let m;
  while ((m = re.exec(parsed.body)) !== null) {
    const v = Number(m[1].replace(/,/g, ''));
    if (!allowed.has(v.toFixed(2))) return { ok: false, why: `AI quoted an amount not in the verified data: ${m[0]}` };
  }
  const first = facts.author.name.split(/\s+/)[0].toLowerCase();
  if (!parsed.body.toLowerCase().includes(first)) return { ok: false, why: 'AI email does not greet the author by name' };
  if (facts.flags.has_pending && !parsed.body.includes(inr(facts.totals.pending))) {
    return { ok: false, why: 'AI email omits the verified total pending amount' };
  }
  for (const b of published) {
    if (!parsed.body.includes(b.title)) return { ok: false, why: `AI email omits book title "${b.title}"` };
  }
  return { ok: true, subject: parsed.subject.trim(), body: parsed.body.trim() };
}

let source = 'template';
let aiProblem = '';
let email = null;

const cand = input.candidates && input.candidates[0];
const text = cand && cand.content && cand.content.parts && cand.content.parts.map((p) => p.text || '').join('');
if (input.error || !text) {
  const why = input.error ? (input.error.message || input.error) : 'empty AI response';
  aiProblem = ('AI call failed: ' + (typeof why === 'string' ? why : JSON.stringify(why))).slice(0, 300);
} else {
  const r = checkAi(text);
  if (r.ok) { source = 'ai'; email = { subject: r.subject, body: r.body }; }
  else aiProblem = r.why;
}
if (!email) email = template();

return [{
  json: {
    subject: email.subject,
    body: email.body,
    summary_text: `Subject: ${email.subject}\n\n${email.body}`,
    source,
    ai_problem: aiProblem,
    totals: facts.totals,
    warnings: facts.warnings,
  },
}];

// Build Failure: single funnel for every failed step. The text goes back to Bubble in the webhook reply,
// where Bubble records it in the Notification Log (Status = Failed, Error = this text).
const j = $input.first().json || {};
let ctx = {};
try { ctx = $('Duplicate Guard').first().json; } catch (e) { ctx = {}; }

let msg = '';
const e = j.error;
if (typeof e === 'string') msg = e;
else if (e && typeof e === 'object') msg = e.message || e.description || JSON.stringify(e);
else if (j.message) msg = j.message;
else msg = JSON.stringify(j);
msg = String(msg).replace(/\s+/g, ' ').slice(0, 400);

return [{
  json: {
    author_id: ctx.author_id,
    execution_id: $execution.id,
    error_text: `[n8n execution ${$execution.id}] ${msg}`,
    failed_at: new Date().toISOString(),
  },
}];
